// gh-2042 — workflow + wiring shape guards.
//
// AC1: a published release is immutable for `fa-*` assets — every workflow
// attach path of an fa-* asset routes through scripts/release_asset_gate.sh
// (the only place `gh release upload` of an fa-* asset may happen), and the
// attach-or-create script routes through the gate too.
// AC2: a release-drift-watch workflow re-verifies the published assets
// against the signed SHA256SUMS after every publish AND on a schedule, and
// pages + auto re-requests release-provenance on drift.
// AC4 (REG): the gh-1832 required-assets gate, the gh-814 trust-anchor drift
// gate and the signature self-check stay exactly where they are, and the
// provenance publish point keeps its signed-manifest precondition.
//
// Static lint over the workflows/scripts — the repo's workflow-shape
// never-again pattern (see ci_release_pending_guard_test.dart).
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

YamlMap jobsOf(String workflowPath) =>
    (loadYaml(read(workflowPath))['jobs']) as YamlMap;

/// `gh release upload` invocations (continuation lines joined) in a workflow.
List<String> uploadBlocks(String workflowPath) {
  final lines = read(workflowPath).split('\n');
  final blocks = <String>[];
  for (var i = 0; i < lines.length; i++) {
    if (!lines[i].contains('gh release upload')) continue;
    final block = <String>[lines[i]];
    while (block.last.trimRight().endsWith(r'\') && i < lines.length - 1) {
      i++;
      block.add(lines[i]);
    }
    blocks.add(block.join(' '));
  }
  return blocks;
}

void main() {
  group('AC1 — every fa-* attach path routes through the immutability gate', () {
    test('scripts/release_asset_gate.sh exists and uploads with --clobber', () {
      final gate = read('scripts/release_asset_gate.sh');
      expect(gate, contains('--clobber'),
          reason: 'the gate performs the attach (or the immutable skip)');
      expect(gate, contains('isDraft'),
          reason: 'the gate decides on the draft/published state');
      expect(gate, contains('fa-'),
          reason: 'the immutability class is exactly the fa-* asset set');
    });

    test('release_attach_or_create.sh routes uploads through the gate', () {
      final attach = read('scripts/release_attach_or_create.sh');
      expect(attach, contains('release_asset_gate.sh'),
          reason: 'the attach-or-create upload path is the v1.0.680 hole — '
              'every upload must pass the gate');
    });

    test('ci.yml + build-macos.yml: bare `gh release upload` lines are SHA256SUMS-only (provenance)', () {
      // The provenance manifest upload is the ONLY raw upload allowed in
      // these workflows: SHA256SUMS(.sig) is not an fa-* asset, and
      // re-uploading it is the sanctioned post-publish remediation
      // (re-running release-provenance for the tag).
      // The provenance manifest upload is the ONLY raw upload allowed:
      // SHA256SUMS(.sig) is not an fa-* asset, and re-uploading it is the
      // sanctioned post-publish remediation (re-running release-provenance
      // for the tag, gh-2042 AC3). build-macos.yml has no provenance job —
      // it must have NO raw upload at all.
      {
        final uploads = uploadBlocks('.github/workflows/build-macos.yml');
        expect(uploads, isEmpty,
            reason: 'build-macos.yml: raw `gh release upload` must not exist — '
                'every fa-* attach routes through scripts/release_asset_gate.sh');
      }
      {
        final uploads = uploadBlocks('.github/workflows/ci.yml');
        expect(uploads, isNotEmpty, reason: 'ci.yml keeps its provenance upload');
        for (final line in uploads) {
          expect(
            line,
            contains('SHA256SUMS'),
            reason:
                'ci.yml: "$line" uploads an fa-* asset raw — route it through '
                'scripts/release_asset_gate.sh (gh-2042 AC1: a published '
                'release is immutable for fa-* assets)',
          );
        }
      }
    });

    test('every fa-* upload call site invokes the gate (ci.yml binaries/web-spa/extension, build-macos legs)', () {
      for (final wf in [
        '.github/workflows/ci.yml',
        '.github/workflows/build-macos.yml',
      ]) {
        expect(read(wf), contains('release_asset_gate.sh'),
            reason: '$wf attaches fa-* assets — the gate must guard them');
      }
    });
  });

  group('AC2 — the release drift watch workflow', () {
    const wfPath = '.github/workflows/release-drift-watch.yml';

    test('workflow exists with publish + schedule + dispatch triggers', () {
      expect(File(wfPath).existsSync(), isTrue,
          reason: '$wfPath must exist (gh-2042 AC2)');
      final y = loadYaml(read(wfPath)) as YamlMap;
      final on = y['on'] as YamlMap;
      expect((on['release'] as YamlMap)['types'].toString(), contains('published'),
          reason: 'after every release publish');
      expect(on['schedule'], isNotNull, reason: 'and on a schedule — drift must not linger');
      expect((on['workflow_dispatch'] as YamlMap)['inputs'], isNotNull,
          reason: 'dispatch is the manual remediation vehicle (any tag)');
    });

    test('the job is bounded, least-privileged, and runs the check + remediation', () {
      final jobs = jobsOf(wfPath);
      expect(jobs, hasLength(1));
      final job = jobs.values.first as YamlMap;
      expect(job['timeout-minutes'], isNotNull, reason: 'every job carries an explicit ceiling');
      final perms = job['permissions'] as YamlMap;
      expect(perms['contents'].toString(), contains('read'),
          reason: 'downloads the release assets');
      expect(perms['actions'].toString(), contains('write'),
          reason: 'the drift auto re-request reruns the provenance job');
      expect(perms['issues'].toString(), contains('write'),
          reason: 'drift pages via a deduplicated issue');
      final steps = (job['steps'] as YamlList).map((s) => s.toString()).join('\n');
      expect(steps, contains('if: failure()'),
          reason: 'remediation fires exactly on a red check');
      expect(steps, contains('release_drift_check.sh'),
          reason: 'the re-download + digest diff live in the repo-owned script '
              '(asserted behaviorally in release_drift_check_test.dart)');
      expect(steps, contains('release_drift_remediate.sh'),
          reason: 'the drift path pages + re-requests provenance');
      expect(steps, contains('if: failure()'),
          reason: 'remediation fires exactly on a red check');
    });
  });

  group('AC4 (REG) — the existing release gates stay exactly where they are', () {
    test('gh-1832 required-assets gate stays a publish-blocking provenance step', () {
      final prov = jobsOf('.github/workflows/ci.yml')['release-provenance'] as YamlMap;
      final steps = (prov['steps'] as YamlList)
          .map((s) => s['name']?.toString() ?? '')
          .toList();
      expect(steps, contains('Assert required release assets (gh-1832 gate)'),
          reason: 'no path publishes assets without the required set');
    });

    test('gh-814 trust-anchor drift gate + signature self-check stay in the sign step', () {
      final prov = jobsOf('.github/workflows/ci.yml')['release-provenance'] as YamlMap;
      final signStep = (prov['steps'] as YamlList)
          .whereType<YamlMap>()
          .firstWhere((s) => s['name'] == 'Build and sign SHA256SUMS');
      final body = signStep['run'].toString();
      expect(body, contains('openssl dgst -sha256 -verify'),
          reason: 'the signature self-check stays');
      expect(body, contains('site/install.sh'),
          reason: 'the gh-814 trust-anchor drift gate stays');
    });

    test('the provenance publish point keeps its signed-manifest precondition', () {
      final prov = jobsOf('.github/workflows/ci.yml')['release-provenance'] as YamlMap;
      final uploadStep = (prov['steps'] as YamlList)
          .whereType<YamlMap>()
          .firstWhere((s) => s['name'] == 'Upload provenance assets');
      final body = uploadStep['run'].toString();
      expect(body, contains('SHA256SUMS'));
      expect(body, contains('--draft=false --latest'),
          reason: 'the flip stays provenance-owned (gh-1801)');
    });
  });
}

// gh-2042 — release_attach_or_create.sh against a PUBLISHED release.
//
// The attach-or-create script's existing-release path (`upload_all`) is the
// v1.0.680 hole: it uploaded with --clobber into whatever release the tag
// resolved to — draft or published. Under AC1 the attach routes every asset
// through scripts/release_asset_gate.sh (published → skip attached fa-* /
// refuse unattached fa-* / allow non-fa), and the recovery publish+latest
// flip NEVER fires on a published release — `gh release edit --latest` on an
// older published release would drag the `latest` badge (and `fa update`)
// backwards to a downgrade.
//
// Reuses the release_hygiene_test.dart fixture harness (stubbed gh).
import 'dart:io';

import 'package:test/test.dart';

import 'release_hygiene_test_support.dart';

void main() {
  AttachOut runAttach(
    String name, {
    String? releaseState,
    List<String> attachedNames = const [],
    List<String> viewSeq = const ['exists'],
    List<String> assets = const ['fa-macos-arm64-mac.zip', 'fa-macos-arm64'],
  }) {
    final dir = Directory(
      '${hygieneFixtureRoot.path}/immutable-$name-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    if (releaseState != null) {
      File('${dir.path}/release-state.txt').writeAsStringSync('$releaseState\n');
    }
    if (attachedNames.isNotEmpty) {
      File(
        '${dir.path}/asset-names.txt',
      ).writeAsStringSync('${attachedNames.join('\n')}\n');
    }
    File('${dir.path}/view-seq.txt').writeAsStringSync('${viewSeq.join('\n')}\n');
    for (final asset in assets) {
      File('${dir.path}/$asset').writeAsStringSync('bytes of $asset');
    }
    File('${dir.path}/release-notes.md').writeAsStringSync('curated notes\n');
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_attach_or_create.sh').absolute.path,
      'v1.2.3',
      ...assets,
    ], workingDirectory: dir.path, environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GITHUB_RUN_ID': '111',
      'GITHUB_JOB': 'release-macos',
    });
    return AttachOut(
      res.exitCode,
      '${res.stdout}${res.stderr}',
      File('${dir.path}/log').readAsLinesSync(),
      File('${dir.path}/last-create-notes.md').existsSync()
          ? File('${dir.path}/last-create-notes.md').readAsStringSync()
          : null,
    );
  }

  test('published release + unattached fa-* assets → attach refuses loud, nothing uploaded', () {
    // a.zip/b.zip stand in for the fa-* DMG/zip stable names the daily
    // release-macos leg attaches (the v1.0.680 shape).
    final run = runAttach('published-fa', releaseState: 'false',
        attachedNames: ['fa-web-spa.zip']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(
      run.log.where((l) => l.contains('release upload')),
      isEmpty,
      reason: 'a refused attach uploads nothing',
    );
    expect(run.log.where((l) => l.contains('release create')), isEmpty,
        reason: 'the release exists — a refusal must not create a twin');
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
  });

  test('published release + already-attached assets → immutable skip, exit 0, no upload', () {
    final run = runAttach('published-skip', releaseState: 'false',
        attachedNames: ['fa-macos-arm64-mac.zip', 'fa-macos-arm64']);
    expect(run.exitCode, 0, reason: run.out);
    expect(run.log.where((l) => l.contains('release upload')), isEmpty);
    expect(run.out.toLowerCase(), contains('skip'));
  });

  test('published release + non-fa assets only → clobber-refresh attaches, exit 0', () {
    // The mobile leg (AAB/IPA/APK — not provenance-covered) keeps its
    // store-refresh contract on published releases.
    final run = runAttach('published-nonfa', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz'],
        assets: ['app-release.aab', 'app-store-release.apk']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log.where((l) => l.contains('release upload v1.2.3 app-release.aab')),
      isNotEmpty,
      reason: 'non-fa assets keep the clobber-refresh path',
    );
  });

  test('published release + servable (SHA256SUMS attached) → NO publish flip (latest never drags backwards)', () {
    // Regression guard for the recovery path: on a DRAFT servable release
    // the attach publishes + flags latest (existing behavior, pinned by
    // release_hygiene_test.dart); on a PUBLISHED one the flip must stay
    // off — `--latest` here would move the badge to an older release.
    final run = runAttach('published-servable', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz', 'SHA256SUMS', 'SHA256SUMS.sig'],
        assets: ['app-release.aab']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log.where((l) => l.contains('release edit')),
      isEmpty,
      reason:
          'a published release is never re-flaged latest by the attach '
          '(gh-2042: latest must never move backwards)',
    );
  });

  test('draft release + fa-* assets → attach unchanged (uploads --clobber)', () {
    // Default fixture state (no release-state.txt) = draft.
    final run = runAttach('draft-fa', attachedNames: []);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains(
        'release upload v1.2.3 fa-macos-arm64-mac.zip --clobber --repo OWNER/REPO',
      ),
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty,
        reason: 'un-servable draft stays unflipped (gh-1801, unchanged)');
  });

  test('draft release + servable → recovery publish + latest (unchanged)', () {
    final run = runAttach('draft-servable',
        attachedNames: ['SHA256SUMS', 'SHA256SUMS.sig']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release edit v1.2.3 --draft=false --latest --repo OWNER/REPO'),
      reason: 'the draft recovery path stays (gh-1801 rework)',
    );
  });

  test('release_lazy_draft.sh on a published release → still a no-op skip (the gate owns refusal)', () {
    // lazy_draft only CREATES; its callers' uploads are gated. Its
    // existing-release skip must stay a green no-op for all states.
    final dir = Directory(
      '${hygieneFixtureRoot.path}/immutable-lazy-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    File('${dir.path}/release-state.txt').writeAsStringSync('false\n');
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_lazy_draft.sh').absolute.path,
      'v1.2.3',
    ], workingDirectory: dir.path, environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GITHUB_RUN_ID': '111',
      'GITHUB_JOB': 'binaries-linux-x64',
    });
    expect(res.exitCode, 0, reason: '${res.stdout}${res.stderr}');
    final log = File('${dir.path}/log').readAsLinesSync();
    expect(log.where((l) => l.contains('release create')), isEmpty);
  });
}

